SET statement_timeout = 0;

-- Generated historical CEC election/race migration.

WITH input(external_id, name, slug, region_type) AS (
    VALUES
    ('cec-historical-county-kaohsiung', '高雄縣', 'historical-kaohsiung-county', 'county'),
    ('cec-historical-county-taichung', '臺中縣', 'historical-taichung-county', 'county'),
    ('cec-historical-county-taipei', '臺北縣', 'historical-taipei-county', 'county'),
    ('cec-historical-county-tainan', '臺南縣', 'historical-tainan-county', 'county')
)
INSERT INTO regions (external_id, name, slug, region_type, is_public, updated_at)
SELECT external_id, name, slug, region_type, FALSE, NOW()
FROM input
ON CONFLICT (external_id) DO UPDATE SET
    name = EXCLUDED.name,
    slug = EXCLUDED.slug,
    region_type = EXCLUDED.region_type,
    is_public = FALSE,
    updated_at = NOW();

WITH input(external_id, name, year, election_type) AS (
    VALUES
    ('cec-historical-election-6d0a0c3e493c2e47', '1994年直轄市及縣市議員選舉', 1994, 'councilor'),
    ('cec-historical-election-a275bfcd53f64b5f', '1998年直轄市及縣市議員選舉', 1998, 'councilor'),
    ('cec-historical-election-64eb47f415a89d1f', '2002年直轄市及縣市議員選舉', 2002, 'councilor'),
    ('cec-historical-election-29d25dce67cee6db', '2005年直轄市及縣市議員選舉', 2005, 'councilor'),
    ('cec-historical-election-17e9e7ed145f650a', '2006年直轄市及縣市議員選舉', 2006, 'councilor'),
    ('cec-historical-election-ab20845d085c445b', '2009年直轄市及縣市議員選舉', 2009, 'councilor'),
    ('cec-historical-election-00f5c690fb4dddc2', '2010年直轄市及縣市議員選舉', 2010, 'councilor'),
    ('cec-historical-election-5d2d565cde864a14', '2014年直轄市及縣市議員選舉', 2014, 'councilor')
)
INSERT INTO elections (
    external_id, name, year, election_type, voting_date, status,
    source_name, source_url, is_public, updated_at
)
SELECT
    external_id, name, year, election_type, NULL, 'completed',
    '中央選舉委員會開放資料', 'https://data.gov.tw/dataset/13119', FALSE, NOW()
FROM input
ON CONFLICT (external_id) DO UPDATE SET
    name = EXCLUDED.name,
    year = EXCLUDED.year,
    election_type = EXCLUDED.election_type,
    status = EXCLUDED.status,
    source_name = EXCLUDED.source_name,
    source_url = EXCLUDED.source_url,
    is_public = FALSE,
    updated_at = NOW();

UPDATE elections AS election
SET name = input.name,
    election_type = input.election_type,
    updated_at = NOW()
FROM (VALUES
    ('cec-2012-legislative-yuan', '2012年立法委員選舉', 'legislative'),
    ('cec-2012-president-vice-president', '2012年總統副總統選舉', 'presidential'),
    ('votetw-election-2020-1654535a43', '2020年立法委員選舉', 'legislative'),
    ('votetw-election-2020-ce20f11679', '2020年總統副總統選舉', 'presidential')
) AS input(external_id, name, election_type)
WHERE election.external_id = input.external_id;

